#!/usr/bin/env node
/**
 * Cursor preToolUse / beforeShellExecution hook:
 * block hand-edits (and obvious shell overwrites) of Clay-generated files.
 *
 * Clay's `check-generated` speaks Claude Code's PreToolUse dialect and only
 * reads tool_input.file_path. This wrapper normalizes Cursor payloads and
 * returns Cursor-native allow/deny JSON.
 */
"use strict";

const fs = require("fs");
const path = require("path");

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = [];
    process.stdin.on("data", (c) => chunks.push(c));
    process.stdin.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    process.stdin.on("error", reject);
  });
}

function allow() {
  process.stdout.write(JSON.stringify({ permission: "allow" }) + "\n");
  process.exit(0);
}

function deny(message) {
  const payload = {
    permission: "deny",
    user_message: "Blocked edit to a Clay-generated file.",
    agent_message: message,
  };
  process.stdout.write(JSON.stringify(payload) + "\n");
  // Exit 2 also means deny in Cursor / Claude Code hooks.
  process.exit(2);
}

function projectRoot(payload) {
  const roots = payload.workspace_roots;
  if (Array.isArray(roots) && roots.length > 0) return roots[0];
  return process.cwd();
}

function loadGeneratedPaths(root) {
  const clayPath = path.join(root, ".clay");
  if (!fs.existsSync(clayPath)) return new Map();

  let clay;
  try {
    clay = JSON.parse(fs.readFileSync(clayPath, "utf8"));
  } catch {
    return new Map();
  }

  const map = new Map();
  for (const model of clay.models || []) {
    for (const rel of Object.keys(model.generated_files || {})) {
      map.set(rel, model.path || "unknown");
    }
  }
  return map;
}

function toRelPath(root, filePath) {
  if (!filePath || typeof filePath !== "string") return null;
  const abs = path.resolve(root, filePath);
  const rel = path.relative(root, abs);
  if (!rel || rel.startsWith("..") || path.isAbsolute(rel)) return null;
  return rel.split(path.sep).join("/");
}

function extractCandidatePaths(payload) {
  const input = payload.tool_input;
  const paths = [];

  const push = (value) => {
    if (typeof value === "string" && value.trim()) paths.push(value.trim());
  };

  push(payload.file_path);

  if (input && typeof input === "object" && !Array.isArray(input)) {
    push(input.file_path);
    push(input.path);
    push(input.target_notebook);
    if (Array.isArray(input.paths)) {
      for (const p of input.paths) push(p);
    }
  }

  // Shell / beforeShellExecution
  const command =
    (input && typeof input === "object" && input.command) ||
    payload.command ||
    "";
  if (typeof command === "string" && command) {
    // Only inspect commands that look like they write files.
    const looksLikeWrite =
      /(^|[|&;]\s*)(tee|sed|perl|ruby|python|node|printf|cat|cp|mv|rm|truncate|dd)\b|>|>>/.test(
        command
      );
    if (looksLikeWrite) {
      for (const match of command.matchAll(
        /(?:(?:>{1,2}|tee(?:\s+-a)?)\s+)(['"]?)([^\s'";|&]+)\1/g
      )) {
        push(match[2]);
      }
      for (const match of command.matchAll(
        /\b(?:cp|mv|rm|sed|truncate)\b[^|;]*?\s(['"]?)([^\s'";|&]+)\1\s*$/g
      )) {
        push(match[2]);
      }
    }
  }

  return paths;
}

function blockMessage(relPath, modelPath) {
  return (
    `BLOCKED: ${relPath} is generated by Clay from model ${modelPath}.\n` +
    `\n` +
    `Do NOT edit this file directly. Instead:\n` +
    `  1. Change clay/model.json (or an included model file)\n` +
    `  2. Update templates under clay/generators/\n` +
    `  3. Run \`clay generate\` (or Clay MCP clay_generate)\n` +
    `\n` +
    `See https://morkeleb.github.io/clay/pages/mcp-server.html`
  );
}

async function main() {
  const raw = (await readStdin()).replace(/^\uFEFF+/, "");
  if (!raw.trim()) return allow();

  let payload;
  try {
    payload = JSON.parse(raw);
  } catch {
    return allow();
  }

  const root = projectRoot(payload);
  const generated = loadGeneratedPaths(root);
  if (generated.size === 0) return allow();

  for (const candidate of extractCandidatePaths(payload)) {
    const rel = toRelPath(root, candidate);
    if (rel && generated.has(rel)) {
      return deny(blockMessage(rel, generated.get(rel)));
    }
  }

  return allow();
}

main().catch(() => allow());
